return {["fb20_01"]={["dsc"]=[[襄阳城正南门，因四象中的朱雀代表南方而得名。近年来蒙古屡次侵犯襄阳城，故这儿把守相当严密，一些官兵们正在盘查要离襄阳城的人。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb20_01]],["item1"]=[[fb20item1]],["name"]=[[朱雀门]],["permission"]=1,["role1"]=[[fb20r01_1]],["role2"]=[[fb20r01_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb20_03]],["visible"]=1},["fb20_02"]={["dsc"]=[[这里到处都是官兵，有的在武将的指挥下列队操练，有的在休息。南墙下坐着主帅，不动声色地寻视着四周。看到你进来，他们全都瞪大眼睛盯着你。]],["enterable"]=1,["id"]=[[fb20_02]],["name"]=[[兵营]],["permission"]=2,["right"]=[[fb20_03]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb20_03"]={["down"]=[[fb20_01]],["dsc"]=[[这里是襄阳城南大街，南面是朱雀门，北边非常热闹。东边是为襄阳城守军打制铠甲武器的兵器铺。西面是襄阳城的南兵营，隐隐能听见里面传来的兵士们的操练声。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb20_03]],["item1"]=[[bfitem1]],["item2"]=[[fb20fyb]],["item3"]=[[wldhpd]],["item4"]=[[fubentiaozhuan2]],["left"]=[[fb20_02]],["leftDown"]=[[fb20_53]],["name"]=[[南大街]],["permission"]=1,["right"]=[[fb20_04]],["stepMusic"]=[[jiaobu]],["up"]=[[fb20_06]],["visible"]=1},["fb20_04"]={["dsc"]=[[这里原来是一家普通的铁匠铺。但近年来蒙古大军屡次进犯襄阳，所以被官府征用，目前用来为襄阳守军打造铠甲、兵器等，只见几十个铁匠正叮叮当当地忙个不停。]],["enterable"]=1,["id"]=[[fb20_04]],["item1"]=[[duanzaoronglu1]],["left"]=[[fb20_03]],["name"]=[[铁匠铺]],["permission"]=2,["role1"]=[[fb20r04_1]],["role2"]=[[fb20r04_2]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb20_05"]={["dsc"]=[[这里本是襄阳最大的赌场，可是现在却一片冷清，只因大战当前，为免军纪败坏，官府将其封闭了。]],["enterable"]=1,["id"]=[[fb20_05]],["item1"]=[[fb20item11]],["item2"]=[[fb20item12]],["item3"]=[[bfitem2]],["name"]=[[赌场]],["permission"]=1,["right"]=[[fb20_06]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb20_06"]={["down"]=[[fb20_03]],["dsc"]=[[这里是襄阳城里的繁华地段，虽然久经战火，但在一众江湖豪侠的保卫下，襄阳的老百姓过着非常安安稳稳的生活。西边是襄阳城内最大的一家赌场，东边是“觅香楼”。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb20_06]],["item1"]=[[fb20item101]],["left"]=[[fb20_05]],["name"]=[[南大街]],["permission"]=1,["right"]=[[fb20_07]],["role1"]=[[fb20r06_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb20_09]],["visible"]=1},["fb20_07"]={["dsc"]=[[襄阳城里没有不知道“觅香楼”的。虽是抗战时期，来往公务却多，饭后谈资也富，生意反见兴隆。]],["enterable"]=1,["id"]=[[fb20_07]],["item1"]=[[fb20r07_5]],["left"]=[[fb20_06]],["name"]=[[觅香楼]],["permission"]=2,["role1"]=[[fb20r07_1]],["role2"]=[[fb20r07_2]],["role3"]=[[fb20r07_3]],["role4"]=[[fb20r07_4]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb20_08"]={["dsc"]=[[这里是襄阳的钱庄，因为这里商业相当发达，各地的商号都和这里有银钱来往。钱庄里有很多人在存取钱，也有人在兑换银两，生意一片欣荣。]],["enterable"]=1,["id"]=[[fb20_08]],["name"]=[[钱庄]],["permission"]=2,["right"]=[[fb20_09]],["role1"]=[[fb20r08_1]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb20_09"]={["down"]=[[fb20_06]],["dsc"]=[[这是一条宽阔的青石板街道。南边通往朱雀门，北面是中央广场，西面是钱庄，东面是襄阳城内的唯一一家学堂，隐隐能听到学堂里传来学生们朗朗地读书声。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb20_09]],["left"]=[[fb20_08]],["name"]=[[南大街]],["permission"]=1,["right"]=[[fb20_10]],["role1"]=[[fb20r09_1]],["role2"]=[[znq3cd01a]],["stepMusic"]=[[jiaobu]],["up"]=[[fb20_21]],["visible"]=1},["fb20_10"]={["dsc"]=[[这里是襄阳的学堂，一位庄重严肃的老先生坐在太师椅上讲学。在他的两侧坐满了求学的学生。一张古意盎然的书案放在老先生的前面，案上摆着几本翻开了的线装书籍。]],["enterable"]=1,["id"]=[[fb20_10]],["left"]=[[fb20_09]],["name"]=[[学堂]],["permission"]=2,["role1"]=[[fb20r10_1]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb20_11"]={["dsc"]=[[这是襄阳守军用来校阅军士的地方。只见校场正中巍巍搭着一座高台，台前竖着两根旗杆，旗杆顶上有着硕大的旗斗。校场里聚集着数百个四袋以上的丐帮弟子。他们都是来竞选新任丐帮帮主的。]],["enterable"]=1,["fightBackground"]=[[擂台]],["id"]=[[fb20_11]],["name"]=[[大校场]],["permission"]=2,["role1"]=[[fb20r11_1]],["role2"]=[[fb20r11_2]],["role3"]=[[fb20r11_3]],["role4"]=[[fb20r11_4]],["stepMusic"]=[[jiaobu]],["up"]=[[fb20_18]],["visible"]=1},["fb20_12"]={["dsc"]=[[这里是襄阳安抚使按照郭大侠的意思建造用来安置各地前来效力的义士的地方。南面是一条长长的通廊，东西两边是练武场。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb20_12]],["item1"]=[[fb20item5]],["item2"]=[[fb20item9]],["item3"]=[[fb20item9]],["name"]=[[聚义馆]],["permission"]=1,["role1"]=[[fb20r12_1]],["role2"]=[[fb20r12_2]],["role3"]=[[fb20r12_3]],["stepMusic"]=[[jiaobu]],["up"]=[[fb20_19]],["visible"]=1},["fb20_13"]={["dsc"]=[[这是家远近闻名的当铺，柜台后的老板头也不抬的只顾拨拉着算盘，柜台上方挂着一块花木牌子。据街坊们说当铺给的价还不算坏，并且从不问货的来处，所以生意很不错。]],["enterable"]=1,["id"]=[[fb20_13]],["name"]=[[当铺]],["permission"]=2,["role1"]=[[fb20r13_1]],["role2"]=[[fb20r13_100]],["stepMusic"]=[[jiaobu]],["up"]=[[fb20_20]],["visible"]=1},["fb20_14"]={["dsc"]=[[药铺不大，却异常的整洁；正面是柜台，柜台后面是个大柜子几百个小抽屉上一一用红纸标着药材的名称、几个伙计正在分拣刚刚收购来的草药。]],["enterable"]=1,["id"]=[[fb20_14]],["item1"]=[[lylitem1]],["name"]=[[药铺]],["permission"]=2,["role1"]=[[fb20r14_1]],["role2"]=[[fb20r14_100]],["role3"]=[[fb20r14_101]],["stepMusic"]=[[jiaobu]],["up"]=[[fb20_22]],["visible"]=1},["fb20_15"]={["dsc"]=[[这儿是襄阳最有名的大戏院，在全国各地也有很大的名气，由这个戏院组织的戏班子常常到各地去进行表演，非常的受好评。你可以在这儿向管事打听有关工作的事。]],["enterable"]=1,["fightBackground"]=[[襄阳戏院]],["id"]=[[fb20_15]],["item1"]=[[fb20item106]],["item2"]=[[2qiaddmugui]],["name"]=[[襄阳戏院]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb20_23]],["visible"]=1},["fb20_16"]={["dsc"]=[[这是一家简陋的木匠铺，一个中年木匠正蹲在地上钉东西。地上和墙角凌乱地堆放着一些木剑，木刀，木棍什么的，还有几件像锯子，刨子一类的木匠工具。]],["enterable"]=1,["id"]=[[fb20_16]],["name"]=[[木匠铺]],["permission"]=2,["role1"]=[[fb20r16_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb20_24]],["visible"]=1},["fb20_17"]={["dsc"]=[[这里是襄阳城的西城门，因四象中的白虎代表西方而得名。近年来蒙古屡次侵犯襄阳城，故这儿把守相当严密，一些官兵们正在盘查要离襄阳城的人。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb20_17]],["name"]=[[白虎门]],["permission"]=2,["right"]=[[fb20_18]],["role1"]=[[fb20r17_1]],["role2"]=[[fb20r17_2]],["role3"]=[[fb20r17_3]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb20_18"]={["down"]=[[fb20_11]],["dsc"]=[[这是一条宽阔的青石街道，西面是白虎内门，东边是一个大十字街口，只见人来人往，络绎不绝。南边是大校场。北面是襄阳城的西兵营。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb20_18]],["item1"]=[[fubentiaozhuan3]],["left"]=[[fb20_17]],["leftDown"]=[[fb20_54]],["name"]=[[西大街]],["permission"]=2,["right"]=[[fb20_19]],["role1"]=[[fb20r18_1]],["role2"]=[[fb20r18_100]],["role3"]=[[fb20r18_101]],["stepMusic"]=[[jiaobu]],["up"]=[[fb20_27]],["visible"]=1},["fb20_19"]={["down"]=[[fb20_12]],["dsc"]=[[这里是很大的十字街口，北边是西内大街，南面是一座彩楼，楼前高高的挂着一方大匾，上面用正楷写着“聚义馆”。东边通向中央广场，西面可达白虎门。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb20_19]],["left"]=[[fb20_18]],["name"]=[[西大街]],["permission"]=1,["right"]=[[fb20_20]],["role1"]=[[fb20r19_1]],["role2"]=[[fb20r19_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb20_29]],["visible"]=1},["fb20_20"]={["down"]=[[fb20_13]],["dsc"]=[[这是一条宽阔的青石板街道，西边是一个大十字街口。东面是襄阳的中央广场，北边是郭大侠郭靖的府邸大门。南面是一家当铺，听说里面常能买到你所需的东西。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb20_20]],["left"]=[[fb20_19]],["name"]=[[西大街]],["permission"]=1,["right"]=[[fb20_21]],["role1"]=[[fb20r20_1]],["role2"]=[[fb20r21_2]],["role3"]=[[fb20r21_3]],["role4"]=[[fb20r20_100]],["stepMusic"]=[[jiaobu]],["up"]=[[fb20_30]],["visible"]=1},["fb20_21"]={["down"]=[[fb20_09]],["dsc"]=[[这里是襄阳的中央广场，铺着青石地面。东面通向青龙门，西面通向白虎门，南面直达朱雀门，远远地你可看到北面是襄阳安抚使衙门，附近有不少官兵正在巡逻。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb20_21]],["left"]=[[fb20_20]],["name"]=[[中央广场]],["permission"]=1,["right"]=[[fb20_22]],["role1"]=[[fb20r21_1]],["role2"]=[[fb20r21_100]],["role3"]=[[fb20r21_101]],["stepMusic"]=[[jiaobu]],["up"]=[[fb20_31]],["visible"]=1},["fb20_22"]={["down"]=[[fb20_14]],["dsc"]=[[这是一条宽阔的青石板街道，东边是一个大十字街口。西面是襄阳的中央广场，北边是襄阳守城大将王坚的府邸大门，那儿守备森严，闲杂人等禁止进入。南面是一家药铺。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb20_22]],["left"]=[[fb20_21]],["name"]=[[东大街]],["permission"]=1,["right"]=[[fb20_23]],["role1"]=[[fb20r22_1]],["role2"]=[[fb20r22_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb20_32]],["visible"]=1},["fb20_23"]={["down"]=[[fb20_15]],["dsc"]=[[这儿是很大的十字街口，北边是东内大街，南面是一条街道，听说有钱人一般都住在里面，东面通向襄阳城的青龙门，向西可到达中央广场。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb20_23]],["item1"]=[[fb20item109]],["item2"]=[[bfitem3]],["left"]=[[fb20_22]],["name"]=[[东大街]],["permission"]=1,["right"]=[[fb20_24]],["role1"]=[[fb20r23_1]],["role2"]=[[2019qxcdg1a]],["role3"]=[[2019qxcdg1b]],["stepMusic"]=[[jiaobu]],["up"]=[[fb20_33]],["visible"]=1},["fb20_24"]={["down"]=[[fb20_16]],["dsc"]=[[这是一条宽阔的青石街道，向东西两头延伸。东面是青龙内门，南边是木匠铺。西边是一个十字街口。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb20_24]],["item1"]=[[fubentiaozhuan4]],["left"]=[[fb20_23]],["name"]=[[东大街]],["permission"]=2,