jiaobu]],["visible"]=1},["fb20_31"]={["down"]=[[fb20_21]],["dsc"]=[[这是安抚使衙门的大门，门为精钢所著，坚固异常。大门紧闭，里面却传出一阵阵嬉笑声，和门口的肃杀很不协调。想来这个安抚使大人的日子还是过得蛮滋润。]],["enterable"]=1,["fightBackground"]=[[安抚使衙门]],["id"]=[[fb20_31]],["name"]=[[安抚使衙门]],["permission"]=2,["role1"]=[[fb20r31_1]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb20_32"]={["down"]=[[fb20_22]],["dsc"]=[[这是将军府的大门，门板以精铁所著，坚固无比。门上面挂着一块巨大的牌坊，上书「将军府」三个大字，门前东西两边各肃立着两个腰配大刀的宋兵。]],["enterable"]=1,["id"]=[[fb20_32]],["name"]=[[将军府]],["permission"]=2,["role1"]=[[fb20r32_1]],["role2"]=[[xiangyang003]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb20_33"]={["down"]=[[fb20_23]],["dsc"]=[[这是一条青石铺就的大街。西面是襄阳守城大将王坚的府邸大院。东面是一座镖局，北面是用青石铺的大街道。南面是一个大的十字街道，只见人来人往，非常热闹。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb20_33]],["name"]=[[东内大街]],["permission"]=1,["right"]=[[fb20_34]],["role1"]=[[fb20r33_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb20_37]],["visible"]=1},["fb20_34"]={["dsc"]=[[你来到一座结构宏伟的建筑前，左右石坛上各插着一根两丈多高的旗杆，右首旗子用金线绣着一头张牙舞爪的狮子，左首旗子上写着“福威镖局襄阳分号”八个大字。]],["enterable"]=1,["id"]=[[fb20_34]],["left"]=[[fb20_33]],["name"]=[[镖局]],["permission"]=2,["role1"]=[[fb20r34_1]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb20_35"]={["dsc"]=[[这里的老板刚从南阳搬来，听说以前他曾在嵩山少林寺出过家，后不知什么原因又还了俗，专门卖书为生。只见书店面积很大，以前曾是一座勾栏。]],["enterable"]=1,["id"]=[[fb20_35]],["name"]=[[书店]],["permission"]=2,["right"]=[[fb20_36]],["role1"]=[[fb20r35_1]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb20_36"]={["down"]=[[fb20_29]],["dsc"]=[[这是一条青石铺就的大街。北面是十字街口。隐隐地能望见南面是一座很高的彩楼，东面是一堵盖着红色琉璃瓦的高墙，里面是郭府大院。西面是书店。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb20_36]],["left"]=[[fb20_35]],["name"]=[[西内大街]],["permission"]=1,["role1"]=[[fb20r36_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb20_40]],["visible"]=1},["fb20_37"]={["down"]=[[fb20_33]],["dsc"]=[[这是一条青石铺就的大街。西面是襄阳守城大将王坚的府衙。东面是忠烈祠，北面是一个十字街道，只见人来人往，非常热闹，南面是用青石铺的街道。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb20_37]],["name"]=[[东内大街]],["permission"]=1,["right"]=[[fb20_38]],["role1"]=[[fb20r37_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb20_44]],["visible"]=1},["fb20_38"]={["dsc"]=[[这里是襄阳城的忠烈祠，十余年来为保卫襄阳而牺牲的烈士名讳都刻在这里，每个有爱国心的人到这都会来祭奠一下忠魂。]],["id"]=[[fb20_38]],["left"]=[[fb20_37]],["name"]=[[忠烈祠]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb20_39"]={["dsc"]=[[这里是襄阳城内老百姓的居住区。只见胡同两边是有些小店面，有米行、小杂货铺等。一些居民从这里进进出出。]],["id"]=[[fb20_39]],["item1"]=[[fb20item104]],["item2"]=[[fb20item104]],["item3"]=[[fb20item104]],["name"]=[[胡同]],["permission"]=2,["right"]=[[fb20_40]],["role1"]=[[fb20r39_1]],["role2"]=[[fb20r39_100]],["role3"]=[[fb20r39_103]],["role4"]=[[fb20r39_101]],["stepMusic"]=[[jiaobu]]},["fb20_40"]={["down"]=[[fb20_36]],["dsc"]=[[因为这儿是十字街口，所以非常热闹。小商小贩们在向行人吆喝着，兜售他们的商品。西面是小弄，许多襄阳城的老百姓住在里面，南面和西面是青石铺就的大街。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb20_40]],["item1"]=[[fb20item100]],["left"]=[[fb20_39]],["name"]=[[大街口]],["permission"]=1,["right"]=[[fb20_41]],["role1"]=[[fb20r40_1]],["role2"]=[[fb20r40_2]],["stepMusic"]=[[jiaobu]]},["fb20_41"]={["dsc"]=[[这是一条用青石铺就的大道。只见北面是新罗坊。向东就是丁字街口，西面也是一个大街口，你好像看到一条大街通向南面。南面是郭大侠的府邸。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb20_41]],["left"]=[[fb20_40]],["name"]=[[北内大街]],["permission"]=1,["right"]=[[fb20_42]],["role1"]=[[fb20r41_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb20_46]]},["fb20_42"]={["dsc"]=[[这里是襄阳北部的丁字街口。向北一直通向玄武门，东面和西面是一条笔直的青石大街，通向城内。南面是一堵上盖红色琉璃瓦的高墙，里面是镇守襄阳的将官的府邸。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb20_42]],["left"]=[[fb20_41]],["name"]=[[丁字街口]],["permission"]=1,["right"]=[[fb20_43]],["role1"]=[[fb20r42_1]],["role2"]=[[fb20r42_2]],["role3"]=[[fb20r42_3]],["stepMusic"]=[[jiaobu]],["up"]=[[fb20_48]]},["fb20_43"]={["dsc"]=[[这是一条用青石铺就的大道。只见北面不时的有马车飞奔而出。向西就是丁字街口，东面也是一个大街口。南面是一堵上盖红色琉璃瓦的高墙，里面是襄阳守城大将王坚的府邸。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb20_43]],["item1"]=[[fubentiaozhuan1]],["left"]=[[fb20_42]],["name"]=[[北内大街]],["permission"]=1,["right"]=[[fb20_44]],["role1"]=[[fb20r43_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb20_52]]},["fb20_44"]={["down"]=[[fb20_37]],["dsc"]=[[因为这儿是十字街口，所以非常热闹。小商小贩们在向行人吆喝着，兜售他们的商品。北面是马厩，东面是小弄，许多襄阳城的老百姓住在里面，南面和西面是青石铺就的大街。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb20_44]],["left"]=[[fb20_43]],["name"]=[[大街口]],["permission"]=1,["right"]=[[fb20_45]],["role1"]=[[fb20r44_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb20_50]]},["fb20_45"]={["dsc"]=[[这里是襄阳城内老百姓的居住区。只见小弄两边是有些小店面，有米行、小杂货铺等。一些居民从这里进进出出。]],["id"]=[[fb20_45]],["left"]=[[fb20_44]],["name"]=[[小弄]],["permission"]=2,["role1"]=[[fb20r45_1]],["role2"]=[[fb20r45_100]],["role3"]=[[fb20r45_101]],["role4"]=[[fb20r45_102]],["stepMusic"]=[[jiaobu]]},["fb20_46"]={["down"]=[[fb20_41]],["dsc"]=[[虽然新罗已被高丽所灭，但这些年来一直将这里称为新罗坊，于是也就一直延续下来，不少高丽人会带着货物来这里贩售，没见过异国事物的人们经常来这看看。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb20_46]],["name"]=[[新罗坊]],["permission"]=1,["role1"]=[[fb20r46_1]],["role2"]=[[fb20r46_2]],["stepMusic"]=[[jiaobu]]},["fb20_47"]={["dsc"]=[[这里到处都是官兵，有的在武将的指挥下列队操练，有的在休息。南墙下坐着主帅，不动声色地寻视着四周。看到你进来，他们全都瞪大眼睛盯着你。]],["id"]=[[fb20_47]],["name"]=[[兵营]],["permission"]=2,["right"]=[[fb20_48]],["role1"]=[[fb20r47_1]],["role2"]=[[fb20r47_2]],["role3"]=[[fb20r47_3]],["role4"]=[[fb20r47_4]],["stepMusic"]=[[jiaobu]]},["fb20_48"]={["down"]=[[fb20_42]],["dsc"]=[[这是一条宽阔的青石街道，向南北两头延伸。北面是玄武内门，南边显得很繁忙。东边是一茶馆。西面是襄阳城的北兵营，隐隐能听见里面传来的操练声。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb20_48]],["item1"]=[[fb20item102]],["item2"]=[[fb20item105]],["left"]=[[fb20_47]],["name"]=[[北大街]],["permission"]=1,["right"]=[[fb20_49]],["role1"]=[[fb20r48_100]],["role2"]=[[fb20r48_101]],["stepMusic"]=[[jiaobu]],["up"]=[[fb20_51]]},["fb20_49"]={["dsc"]=[[你一走进来，就闻到一股茶香沁入心脾，精神为之一爽。几张八仙桌一字排开，坐满了客人，或高声谈论战局，或交头接耳元兵势大。你要想打听什么，恐怕不是时候。]],["id"]=[[fb20_49]],["left"]=[[fb20_48]],["name"]=[[茶馆]],["permission"]=1,["role1"]=[[fb20r49_1]],["role2"]=[[fb20r49_2]],["role3"]=[[fb20r49_3]],["role4"]=[[fb20r49_4]],["stepMusic"]=[[jiaobu]]},["fb20_50"]={["down"]=[[fb20_44]],["dsc"]=[[这里是襄阳城内唯一一家车马行，你可以花钱去往任意地方。近来因为郭夫人正在组织人力四处搜集防城材料，所以这里车来车往，络绎不绝。]],["id"]=[[fb20_50]],["name"]=[[马厩]],["permission"]=2,["role1"]=[[fb20r50_1]],["stepMusic"]=[[jiaobu]]},["fb20_51"]={["down"]=[[fb20_48]],["dsc"]=[[这里是襄阳城的北城门，因四象中的玄武代表北方而得名。近